CRITERIA_CODES = [
    "S1","S2","S3","S4","S5",
    "W1","W2","W3","W4","W5",
    "O1","O2","O3","O4","O5",
    "T1","T2","T3","T4","T5",
]

ACTIVITY_MAP: dict[str, str] = {
    "Sales, Procurement":              "sales",
    "Finance, Accounting, Banks":      "finance",
    "Production":                      "production",
    "Logistics":                       "logistics",
    "Marketing, Advertising, PR":      "marketing",
    "Construction":                    "construction",
    "Education":                       "education",
    "Medicine":                        "medicine",
    "Transport":                       "transport",
    "IT & Technology":                 "it",
    "Retail / Wholesale":              "retail",
    "Services":                        "services",
}


def get_activity(industry: str | None) -> dict | None:
    if not industry:
        return None
    key = ACTIVITY_MAP.get(industry)
    if not key:
        return None
    return ACTIVITIES.get(key)


def calculate_weights(answers: dict[str, int]) -> dict[str, list[dict]]:
    groups: dict[str, list[str]] = {
        "s": ["S1","S2","S3","S4","S5"],
        "w": ["W1","W2","W3","W4","W5"],
        "o": ["O1","O2","O3","O4","O5"],
        "t": ["T1","T2","T3","T4","T5"],
    }
    result: dict[str, list[dict]] = {}
    for grp, codes in groups.items():
        scores = [max(1, min(5, answers.get(code, 1))) for code in codes]
        total = sum(scores)
        result[grp] = [
            {"code": code, "weight": round(s / total, 4)}
            for code, s in zip(codes, scores)
        ]
    return result
